    conditionsSections: [['Le périmètre', 'Le parcours vise la préparation linguistique et la progression vers les compétences attendues pour NCLC 7. Il ne constitue pas un conseil en immigration.'], ['Le niveau de départ', 'Le test Pathway oriente la première estimation ; une classe en direct confirme les compétences observées avant que le cycle soit défini.'], ['Le suivi', 'Un cycle correspond au travail prévu pour maîtriser un niveau CECRL, comme A1 ou A2. La présence, les tâches et les simulations font partie du parcours convenu.'], ['Ce qui reste exclu', 'Les frais d’examen, les démarches administratives, les déplacements et toute décision d’IRCC restent à la charge du candidat.']],
    privacySections: [['Données utilisées', 'Le formulaire peut préparer votre nom, votre email, votre WhatsApp, votre objectif, votre échéance et les résultats calculés dans le navigateur.'], ['Finalité', 'Ces données servent à répondre à votre demande, proposer un calendrier cohérent et suivre la conversation que vous choisissez d’ouvrir.'], ['WhatsApp et tiers', 'Si vous choisissez WhatsApp, vous décidez d’envoyer le message préparé. Les politiques de WhatsApp, d’email, de Canada.ca et des fontes externes s’appliquent à ces services.'], ['Vos droits', 'Vous pouvez demander l’accès, la correction ou la suppression des informations en écrivant à pathway.l.s.sectoram@gmail.com.']],
    resourceSections: [['TEF Canada et TCF Canada', 'Les quatre compétences sont évaluées séparément. Une préparation utile travaille le format, la gestion du temps et les tâches attendues.'], ['NCLC 7', 'Le niveau doit être observé en compréhension orale, compréhension écrite, expression orale et expression écrite ; une force ne compense pas automatiquement une autre faiblesse.'], ['Un rythme qui tient', 'Les rythmes de 2 à 6 heures par semaine servent à construire un scénario à partir du niveau réel et de la régularité disponible.'], ['Québec et autres projets', 'TEFAQ, TCF Québec et Express Entry ne sont pas les mêmes parcours. Le bon examen dépend du projet administratif exact.']],
    thanksSteps: [['01', 'Nous relisons votre scénario', 'Niveau, objectif, rythme et disponibilités sont vérifiés ensemble.'], ['02', 'Nous confirmons un créneau', 'Aucun paiement ne bloque un horaire avant la confirmation écrite.'], ['03', 'Nous préparons le prochain pas', 'Vous recevez une recommandation claire ou un lien de paiement lorsque le parcours est confirmé.']],
