    nav: ['Methode', 'Erfahrung', 'Lehrkräfte', 'Pläne'], navLabel: 'Hauptnavigation', languageLabel: 'Sprachen', skip: 'Zum Inhalt springen', home: 'Startseite',
    experienceTitle: 'Ein sichtbarer Weg von der ersten Messung bis zur nächsten Stufe.', experienceCopy: 'Jeder Schritt macht aus einer vagen Absicht eine konkrete Entscheidung: Niveau, Rhythmus, Übung und Nachweis.',
    teachersTitle: 'Lehrkräfte, die Ihren Weg wirklich lesen.', teachersCopy: 'Privatunterricht, präzise Korrekturen und eine Begleitung, die Prüfung, Arbeit und verfügbare Energie berücksichtigt.', teachers: [['Ryan', 'Französischlehrer · Fortschritt und Aussprache'], ['Adbrahim', 'Privatunterricht · TEF Canada, TCF Canada und NCLC 7']],
    testimonialsTitle: 'Was Lernende nach dem ersten Durchbruch erzählen.', testimonialsCopy: 'Eine kuratierte Folge von Video- und schriftlichen Erfahrungsberichten in der Pathway-Reihenfolge.', videoLabel: 'Video-Erfahrung', writtenLabel: 'Schriftlicher Bericht', condensed: 'Zusammengefasste Meinung', writtenStories: [['Klare Erklärungen und lebendige Stunden machen Französisch verständlicher.', 'Oscar'], ['Eine geduldige Methode, die zum Weiterlernen zwischen den Stunden motiviert.', 'Majo'], ['Die Begleitung hat meine Fehler in konkrete nächste Schritte verwandelt.', 'Pia'], ['Die Übungen ähneln Prüfungsaufgaben und bewahren trotzdem die menschliche Seite.', 'Jennifer']],
    plansEyebrow: 'Pathway-Pläne', conditionsEyebrow: 'NCLC-7-Zusage', conditionsLead: 'Zyklen, Einstiegsniveau, Anwesenheit und Probetests werden vor der Anmeldung schriftlich bestätigt.', conditionsCta: 'Bedingungen lesen',
    faqTitle: 'Fragen vor dem Start', faq: [['Wie viel Zeit sollte ich einplanen?', 'Der Kalender hängt von Einstiegsniveau, Rhythmus und Prüfungstermin ab. Nach dem Test geben wir ein Szenario, niemals ein automatisches Versprechen.'], ['Bewertet der Test das Sprechen?', 'Lesen, Hören und Grammatik/Wortschatz erhalten /100. Sprechen wird nicht automatisch bewertet und live bestätigt.'], ['Kann ich monatlich beginnen?', 'Ja. Direkte Zykluszahlung kommuniziert 15 % Ermäßigung; ein erster Monat und der Wechsel zu einem Zyklus kommunizieren 10 %.']],
    resourcesEyebrow: 'Ressourcen', resources: [['TEF Canada vorbereiten', 'Vier Fähigkeiten, Prüfungsformat und sinnvolle Vorbereitung.', 'ressources.html'], ['NCLC 7 verstehen', 'Eine Sprachschwelle innerhalb eines vollständigen Profils.', 'conditions-nclc7.html'], ['CRS-Szenario bauen', 'Eine dokumentierte Berechnung ohne Einladungsversprechen.', 'calculateur-crs.html']],
    ctaTitle: 'Ihre nächste Entscheidung darf einfach sein.', ctaCopy: 'Messen Sie den Ausgangspunkt, wählen Sie einen realistischen Rhythmus und fragen Sie die Verfügbarkeit an.', ctaPrimary: 'Test starten', ctaSecondary: 'Rhythmus wählen',
    conditionsSections: [['Geltungsbereich', 'Der Weg unterstützt die Sprachvorbereitung und den Fortschritt zu den für NCLC 7 erwarteten Fähigkeiten. Er ist keine Einwanderungsberatung.'], ['Ausgangsniveau', 'Der Pathway-Test liefert die erste Orientierung; eine Live-Stunde bestätigt beobachtete Fähigkeiten, bevor der Zyklus festgelegt wird.'], ['Begleitung', 'Ein Zyklus entspricht der geplanten Arbeit zum Beherrschen einer GER-Stufe, zum Beispiel A1 oder A2. Anwesenheit, Aufgaben und Probetests gehören zum vereinbarten Weg.'], ['Ausschlüsse', 'Prüfungsgebühren, Verwaltungsverfahren, Reisen und Entscheidungen von IRCC gehören nicht zur Sprachleistung.']],
    privacySections: [['Verwendete Daten', 'Das Formular kann Name, E-Mail, WhatsApp, Ziel, Frist und berechnete Ergebnisse im Browser vorbereiten.'], ['Zweck', 'Diese Angaben dienen der Antwort auf Ihre Anfrage, einem passenden Kalender und der Begleitung des Gesprächs, das Sie eröffnen.'], ['WhatsApp und Dritte', 'Wenn Sie WhatsApp wählen, entscheiden Sie über das Senden der vorbereiteten Nachricht. Für WhatsApp, E-Mail, Canada.ca und externe Schriften gelten deren Richtlinien.'], ['Ihre Rechte', 'Sie können Zugriff, Korrektur oder Löschung per E-Mail an pathway.l.s.sectoram@gmail.com anfragen.']],
    resourceSections: [['TEF Canada und TCF Canada', 'Die vier Fähigkeiten werden getrennt bewertet. Gute Vorbereitung arbeitet an Format, Zeitmanagement und Aufgaben.'], ['NCLC 7', 'Das Niveau muss in Hören, Lesen, Sprechen und Schreiben beobachtet werden; eine Stärke gleicht eine andere Schwäche nicht automatisch aus.'], ['Ein tragfähiger Rhythmus', 'Die wöchentlichen Rhythmen von 2 bis 6 Stunden bauen auf echtem Niveau und verfügbarer Regelmäßigkeit auf.'], ['Québec und andere Projekte', 'TEFAQ, TCF Québec und Express Entry sind verschiedene Wege. Die richtige Prüfung hängt vom genauen Vorhaben ab.']],
    thanksSteps: [['01', 'Wir prüfen Ihr Szenario', 'Niveau, Ziel, Rhythmus und Verfügbarkeit werden gemeinsam geprüft.'], ['02', 'Wir bestätigen einen Termin', 'Vor der schriftlichen Bestätigung blockiert keine Zahlung einen Stundenplan.'], ['03', 'Wir bereiten den nächsten Schritt vor', 'Nach Bestätigung erhalten Sie eine klare Empfehlung oder einen Zahlungslink.']],
